    if any(k in t for k in [
        "покажи ещё", "покажи еще", "следующие объекты", "дальше",
        "другие", "ещё раз", "далее"
    ]) and _is_last_turn_about_catalog(history):
        return {"intent": "data_catalog", "needs_clarification": False}

    # If user asks to continue showing items but last answer was not about catalog,
    # treat as generic continuation/explanation rather than data_catalog.
    if any(k in t for k in [
        "покажи ещё", "покажи еще", "следующие объекты", "дальше",
        "другие", "ещё раз", "далее"
    ]) and not _is_last_turn_about_catalog(history):
        return {"intent": "technical", "needs_clarification": False}

    # Table formatting when facts already present
    if "оформи это таблицей" in t and any(k in last for k in [
        "итого", "сумма", "средний", "количество", "строки", "столбцы",
        "значение", "доход", "оборот", "число", "фильтр", "квартал", "месяц",
        "факт", "ключ", "ответ"
    ]):
        return {"intent": "no_rag", "needs_clarification": False}

    # Month-specific numeric continuation after a numbers-bearing assistant turn
    m = re.search(r"\bа за\s+(\w+)[\?\u0430-я]*\b", t)
    if m and (
        ("за " + m.group(1)) in last and any(x in last for x in ["руб","арк","шт","клиент","остат","сумм","доход","оборот"])
    ):
        return {"intent": "pivot_table", "needs_clarification": False}

    # When user asks about timing and the exact date was already provided above
    if "когда она начинает действовать" in t and re.search(r"\d{1,2}\s+[а-я]+\s+\d{4}", last):
        return {"intent": "no_rag", "needs_clarification": False}
    return None


def _predict_one(history, text):
    t = (text or "").lower()

    # Highest priority: contextual overrides
    ctx = _context(history, t)
    if ctx:
        return ctx

    # Negation flips before affirmative support
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}
    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Work markers suppress polite openings
    if (GREETING_RX.search(t) or GRATITUDE_RX.search(t)) and WORK_RX.search(t):
        pass  # fall through to work-related checks below
    elif GREETING_RX.search(t):
        # Boundary-safe farewell/greeting: exclude bare 'пока' unless part of task like 'пока таблицу'
        if not re.search(r"\bпока\b(?!\s*(?:таблиц|почему|ошибк))", t):
            return {"intent": "greeting", "needs_clarification": False}
    elif GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Order matters: explicit build/edit requests first
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}
    if CATALOG_RX.search(t):
        info_intent = bool(re.search(r"(?:информац|сведени|что у вас)", t))
        has_find = bool(re.search(r"(?:найди|покажи|выведи|где|найти)", t))
        clar = info_intent and not has_find
        return {"intent": "data_catalog", "needs_clarification": clar}
    if CAPABILITIES_RX.search(t):
        return {"intent": "capabilities", "needs_clarification": False}
    if NORAG_RX.search(t):
        return {"intent": "no_rag", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

# regex_based.py
"""Soft regex baseline for 8-class dialogue intent classification.
Deliberately small but incrementally hardened via evolutionary mutations."""
import re
from helper import load_examples, last_assistant

# Core intents — compact yet progressively extended by successful deltas
GREETING_RX = re.compile(
    r"(?:\bпривет\b|\bздравств\b|\bдобр[аоый]\b|\bсвидания\b|\bувидимся\b)"
)
GRATITUDE_RX = re.compile(r"(?:спасибо|благодар|спс|помогло)")
CAPABILITIES_RX = re.compile(
    r"(?:ты умеешь|твои (?:функции|возможности|навыки)|"
    r"кто ты(?: такой)?|\btебе\b|о себе|перечисли (?:свои )?возможности)"
)
SUPPORT_RX = re.compile(
    r"(?:оператор|специалист|поддержк|живой человек|свяжи|пригласи)"
)
CATALOG_RX = re.compile(
    r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис)"
)
PIVOT_RX = re.compile(
    r"(?:сводн|построй|сгруппируй|срез|кросс|отсортируй|поменяй местами|убери разрез|добавь фильтр|перестрой)"
)
NORAG_RX = re.compile(
    r"(?:повтори|сократи|переведи|выпиши|удали|перефразируй|резюме разговора|какой код ошибки я(?: прислал\?)?|про какой продукт мы говорили(?:\?)?)"
)
WORK_RX = re.compile(
    r"(почему|ошибк|не работает|не открывается|не грузится|методик|регламент|что такое|объясни|расскажи|срок|сколько|как счита)"
)

# Negations that flip Support -> Technical
SUPPORT_NEG_RX = re.compile(
    r"(?:не зови|не подключай|оператора не|специалиста не|без оператора|не надо оператора)"
)
NO_THANKS_RX = re.compile(r"\bнет,\s*спасибо\b")
FAREWELL_TASK_RX = re.compile(r"\bпока\b")  # bare farewell


def _collect_prior_assistant_texts(history):
    texts = []
    if not history:
        return texts
    # Scan up to the last 4 assistant messages preceding current turn
    count = 0
    for h in reversed(history):
        if h.get("role") == "assistant" and h.get("content"):
            texts.append((h.get("content") or "").lower())
            count += 1
            if count >= 4:
                break
    return list(reversed(texts))


def _context(history, text):
    t = (text or "").lower()
    last = (last_assistant(history) or "").lower()
    priors = _collect_prior_assistant_texts(history)

    # Menu option disambiguation by last assistant offering
    if any(k in t for k in ["вариант 2", "второе", "пункт б"]):
        if any(k in last for k in ["оператор", "специалист", "человек"]):
            return {"intent": "support", "needs_clarification": False}
        if any(k in last for k in ["объясн", "методик", "подробн", "разбор"]):
            return {"intent": "technical", "needs_clarification": False}

    # Catalog continuation when user asks to continue listing after any recent catalog-bearing answer
    cat_continue_triggers = [
        "покажи ещё", "покажи еще", "следующие объекты", "дальше",
        "другие", "ещё раз", "далее", "другие объекты"
    ]
    if any(k in t for k in cat_continue_triggers):
        hist_texts = ([last] + priors) if last else priors
        if any(any(cat_kw in ht for cat_kw in ["витрин", "таблиц", "куб", "дашборд", "объект данных", "набор данных"]) for ht in hist_texts):
            return {"intent": "data_catalog", "needs_clarification": False}
        return {"intent": "technical", "needs_clarification": False}

    # Table formatting when facts already present in immediate or adjacent assistant answers
    if "оформи это таблицей" in t:
        fact_markers = [
            "итого", "сумма", "средний", "количество", "строки", "столбцы",
            "значение", "доход", "оборот", "число", "фильтр", "квартал", "месяц",
            "построена сводная", "готова сводная"
        ]
        candidates = [last]
        if len(priors) >= 1:
            candidates.append(priors[-1])
        if any(any(m in c for m in fact_markers) for c in candidates):
            return {"intent": "no_rag", "needs_clarification": False}

    # Month-specific numeric continuation after numbers-bearing assistant turn
    m_month = re.search(r"\bа за\s+(\w+)[\?\u0430-я]*\b", t)
    if m_month and (
        ("за" in last and any(x in last for x in ["руб","арк","шт","клиент","остат","сумм","доход","оборот"]))
    ):
        return {"intent": "pivot_table", "needs_clarification": False}

    # Temporal follow-up when date explicitly provided previously -> no_rag
    DATE_RX = re.compile(r"\d{1,2}[ ./-](?:январ|феврал|март|апрел|ма[ий]|июн|июл|август|сентябр|октябр|ноябр|декабр)", re.I)
    if ("когда" in t or "начинает действовать" in t) and any(DATE_RX.search(ht) for ht in ([last] + priors)):
        return {"intent": "no_rag", "needs_clarification": False}

    return None


def _predict_one(history, text):
    t = (text or "").lower()

    # Highest priority: contextual overrides
    ctx = _context(history, t)
    if ctx:
        return ctx

    # Declined further help maps to gratitude before support logic
    if NO_THANKS_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Negation flips before affirmative support
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}
    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Work markers suppress polite openings
    if (re.search(GREETING_RX, t) or GRATITUDE_RX.search(t)) and WORK_RX.search(t):
        pass  # fall through to work-related checks below
    elif GREETING_RX.search(t):
        # Boundary-safe greeting/farewell: allow word-boundary 'пока' only if not part of a task phrase
        has_farewell = bool(FAREWELL_TASK_RX.search(t))
        has_task_tail = "таблиц" in t or "почему" in t or "ошибк" in t or "не открыва" in t
        if has_farewell and not has_task_tail:
            return {"intent": "greeting", "needs_clarification": False}
    elif GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Order matters: explicit build/edit requests first
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}
    if CATALOG_RX.search(t):
        clar = bool(
            re.search(r"(?:информац|сведени)", t)
            and not re.search(r"(?:найди|покажи|выведи|где)", t)
        )
        return {"intent": "data_catalog", "needs_clarification": clar}
    if CAPABILITIES_RX.search(t):
        # Capabilities loses to technical only for explanation-like queries about platforms/products
        if re.search(r"(что такое|что ты знаешь|какие возможности)\s*(платформ|меридиан|призм|зонтик|искра|росинка|пергамент|бастион)", t):
            return {"intent": "technical", "needs_clarification": False}
        return {"intent": "capabilities", "needs_clarification": False}
    if NORAG_RX.search(t):
        verbs = ["повтори","сократи","переведи","выпиши","удали","перефразируй","резюме"]
        ans_candidates = []
        if history:
            if len(history) >= 1 and history[-1].get("role") == "assistant":
                ans_candidates.append((history[-1].get("content") or "").lower())
            if len(history) >= 2 and history[-2].get("role") == "assistant":
                ans_candidates.append((history[-2].get("content") or "").lower())
        structural_anchors = ["определение", "правило", "порог", "итого", "сумма", "средний", "количество", "код", "продукт", "дата", "ключ", "версия"]
        anchor_present = any(any(a in ac for a in structural_anchors) for ac in ans_candidates)
        if any(v in t for v in verbs) and anchor_present:
            return {"intent": "no_rag", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

