    r"(?:оператор|специалист|поддержк|живой человек|свяжи|пригласи|не повторяй инструкцию, лучше позови)"
)
CATALOG_RX = re.compile(
    r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис|где найти|где лежат)"
