        pass  # fall through to work-related checks below
    elif GREETING_RX.search(t):
        # Boundary-safe farewell/greeting: exclude bare 'пока' unless clearly a farewell not followed by tasks
        if re.search(r"\bпока\b", t) and not re.search(r"пока\s+таблиц", t) and not re.search(r"почему|ошибк|не работает|не открывается", t):
            return {"intent": "greeting", "needs_clarification": False}
        else:
            pass  # allow tasky cases to continue
    elif GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

