    r"(почему|ошибк|не работает|не открывается|не грузится|методик|регламент|что такое|объясни|расскажи|срок|сколько)"
)

# Negations that flip Support -> Technical (clause-local where reasonable)
SUPPORT_NEG_RX = re.compile(
    r"(?:не\s+(?:зови|подключай))|оператора\s+не|специалиста\s+не"
)

MONTH_NAMES = [
    "январ","феврал","март","апрел","ма","июн","июл","август",
    "сентябр","октябр","ноябр","декабр"
]

def _context(history, text):
    t = (text or "").lower()
    last = (last_assistant(history) or "").lower()
    # Context-pair disambiguation: operator menu vs explanation menu
    if any(k in t for k in ["вариант 2", "второе", "пункт б", "пункт а"]):
        if any(k in last for k in ["оператор", "специалист", "человек"]):
            return {"intent": "support", "needs_clarification": False}
        if any(k in last for k in ["объясн", "методик", "подробн", "разбор"]):
            return {"intent": "technical", "needs_clarification": False}
    # Continue listing after catalog response
    if any(k in t for k in [
        "покажи ещё", "покажи еще", "следующие объекты", "дальше",
        "другие", "ещё раз", "далее"
    ]) and ("объект" in last or "таблиц" in last or "витрин" in last or "куб" in last):
        return {"intent": "data_catalog", "needs_clarification": False}
    # Table formatting when facts already present (relax strict numeric requirement)
    if "оформи это таблицей" in t and (
        any(k in last for k in [
            "итого", "сумма", "средний", "количество", "строки", "столбцы",
            "значение", "доход", "оборот", "число", "фильтр", "квартал", "месяц"
        ]) or len(last.split()) > 3
    ):
        return {"intent": "no_rag", "needs_clarification": False}
    # Month-specific numeric continuation after a numbers-bearing assistant turn
    if re.search(r"\bа за\s+\w+[\?\u0430-я]*\b", t) and (
        "за" in last and any(x in last for x in ["руб","арк","шт","клиент","остат","сумм","доход","оборот"])
    ):
        return {"intent": "pivot_table", "needs_clarification": False}
    # Same pattern but allow plain month name without explicit numerics
    m = re.search(r"\bа за\s+(\w+)[\?\u0430-я]*\b", t)
    if m and m.group(1).startswith(tuple(MONTH_NAMES)):
        return {"intent": "pivot_table", "needs_clarification": False}
    return None


def _predict_one(history, text):
    t = (text or "").lower()

    # Highest priority: contextual overrides
    ctx = _context(history, t)
    if ctx:
        return ctx

    # Negation flips before affirmative support
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}
    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Work markers suppress polite openings
    if (GREETING_RX.search(t) or GRATITUDE_RX.search(t)) and WORK_RX.search(t):
        pass  # fall through to work-related checks below
    elif GREETING_RX.search(t):
        # Boundary-safe farewell/greeting: exclude bare 'пока' unless it's part of a task phrase
        has_farewell = bool(re.search(r"\bпока\b", t))
        has_task_tail = "таблиц" in t or "почему" in t or "ошибк" in t or "не открыва" in t
        if has_farewell and not has_task_tail:
            return {"intent": "greeting", "needs_clarification": False}
    elif GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Order matters: explicit build/edit requests first
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}
    if CATALOG_RX.search(t):
        has_search = bool(re.search(r"(?:найди|покажи|выведи|где)", t))
        clar = bool(
            re.search(r"(?:информац|сведени)", t)
            and re.search(r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис)", t)
            and not has_search
        )
        if not has_search and not clar:
            # Ambiguous mention without search verb → require clarification only when info-intent plus catalog nouns
            return {"intent": "data_catalog", "needs_clarification": True}
        return {"intent": "data_catalog", "needs_clarification": clar}
    # Capabilities must be checked before the generic platform/product early win
    if CAPABILITIES_RX.search(t):
        return {"intent": "capabilities", "needs_clarification": False}
    # Early technical win on platform/product questions over other heuristics
    if re.search(r"\b(платформ|меридиан|призм)\b", t):
        return {"intent": "technical", "needs_clarification": False}
    if NORAG_RX.search(t):
        return {"intent": "no_rag", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

# regex_based.py
"""Soft regex baseline for 8-class dialogue intent classification.
Deliberately small but incrementally hardened via evolutionary mutations."""
import re
from helper import load_examples, last_assistant

# Core intents — compact yet progressively extended by successful deltas
GREETING_RX = re.compile(
    r"(?:\bпривет\b|\bздравств\b|\bдобр[аоый]\b|\bсвидания\b|\bувидимся\b)"
)
GRATITUDE_RX = re.compile(r"(?:спасибо|благодар|спс|помогло)")
CAPABILITIES_RX = re.compile(
    r"(?:ты умеешь|твои (?:функции|возможности|навыки)|"
    r"кто ты(?: такой)?|\bкто ты\b|о себе|перечисли (?:свои )?возможности|что ваще может|тебе)"
)
SUPPORT_RX = re.compile(
    r"(?:оператор|специалист|поддержк|живой человек|свяжи|пригласи)"
)
CATALOG_RX = re.compile(
    r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис)"
)
PIVOT_RX = re.compile(
    r"(?:сводн|построй|сгруппируй|срез|кросс|отсортируй|поменяй местами|убери разрез|добавь фильтр|сделай таблиц|табличку)"
)
NORAG_RX = re.compile(
    r"(?:повтори|сократи|переведи|выпиши|удали|перефразируй|резюме разговора|какой код ошибки я|про какой продукт мы говорили)"
)
WORK_RX = re.compile(
    r"(почему|ошибк|не работает|не открывается|не грузится|методик|регламент|что такое|объясни|расскажи|срок|сколько)"
)

# Negations that flip Support -> Technical
SUPPORT_NEG_RX = re.compile(
    r"(?:не зови|не подключай|оператора не|специалиста не|без оператора|не надо оператора)"
)
NO_THANKS_RX = re.compile(r"\bнет,\s*спасибо\b")
FAREWELL_TASK_RX = re.compile(r"\bпока\b")  # bare 'пока' as farewell


def _context(history, text):
    t = (text or "").lower()
    last = (last_assistant(history) or "").lower()
    prior_last = ""
    if history:
        for h in reversed(history):
            if h.get("role") == "assistant" and h.get("content"):
                prior_last = h["content"].lower()
                break

    # Menu option disambiguation by last assistant offering
    if any(k in t for k in ["вариант 2", "второе", "пункт б"]):
        if any(k in last for k in ["оператор", "специалист", "человек"]):
            return {"intent": "support", "needs_clarification": False}
        if any(k in last for k in ["объясн", "методик", "подробн", "разбор"]):
            return {"intent": "technical", "needs_clarification": False}

    # Catalog continuation: broader lookback over the last few assistant messages
    if any(k in t for k in ["покажи ещё", "покажи еще", "дальше", "следующие", "другие", "ещё раз", "далее"]):
        cat_keywords = ["витрин", "таблиц", "куб", "дашборд", "объект данных", "набор данных"]
        window = []
        for h in reversed(history):
            if h.get("role") == "assistant" and h.get("content"):
                window.append(h["content"].lower())
                if len(window) >= 4:
                    break
        if any(any(k in msg for k in cat_keywords) for msg in window):
            return {"intent": "data_catalog", "needs_clarification": False}
        return {"intent": "technical", "needs_clarification": False}

    # Table formatting when facts already present in the immediate last answer
    if "оформи это таблицей" in t:
        fact_markers = [
            "итого", "сумма", "средний", "количество", "строки", "столбцы",
            "значение", "доход", "оборот", "число", "фильтр", "квартал", "месяц"
        ]
        if any(k in last for k in fact_markers):
            return {"intent": "no_rag", "needs_clarification": False}

    # Month-specific numeric continuation after a numbers-bearing assistant turn
    m_month = re.search(r"\bа за\s+(\w+)[\?\u0430-я]*\b", t)
    if m_month and (
        "за" in last and any(x in last for x in ["руб","арк","шт","клиент","остат","сумм","доход","оборот"])
    ):
        return {"intent": "pivot_table", "needs_clarification": False}

    # Temporal follow-up when date explicitly provided previously -> no_rag
    DATE_RX = re.compile(r"\d{1,2}[ ./-](?:январ|феврал|март|апрел|ма[ий]|июн|июл|август|сентябр|октябр|ноябр|декабр)", re.I)
    if ("когда" in t or "начинает действовать" in t) and DATE_RX.search(last):
        return {"intent": "no_rag", "needs_clarification": False}

    return None


def _predict_one(history, text):
    t = (text or "").lower()

    # Highest priority: contextual overrides
    ctx = _context(history, t)
    if ctx:
        return ctx

    # Declined further help maps to gratitude before support logic
    if NO_THANKS_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Negation flips before affirmative support
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}
    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Work markers suppress polite openings
    if (re.search(GREETING_RX, t) or GRATITUDE_RX.search(t)) and WORK_RX.search(t):
        pass  # fall through to work-related checks below
    elif GREETING_RX.search(t):
        # Boundary-safe greeting/farewell: exclude 'пока' inside task contexts like 'пока таблицу'
        has_farewell = bool(FAREWELL_TASK_RX.search(t))
        has_task_tail = "таблиц" in t or "почему" in t or "ошибк" in t or "не открыва" in t
        if has_farewell and not has_task_tail:
            return {"intent": "greeting", "needs_clarification": False}
    elif GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Order matters: explicit build/edit requests first
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}
    if CATALOG_RX.search(t):
        clar = bool(
            re.search(r"(?:информац|сведени)", t)
            and not re.search(r"(?:найди|покажи|выведи|где)", t)
        )
        return {"intent": "data_catalog", "needs_clarification": clar}
    if CAPABILITIES_RX.search(t):
        # Capabilities loses to technical only for explanation-like queries about platforms/products
        if re.search(r"(что такое|что ты знаешь|какие возможности).*\b(платформ|меридиан|призм|зонтик|искра|росинка|пергамент|бастион)\b", t):
            return {"intent": "technical", "needs_clarification": False}
        return {"intent": "capabilities", "needs_clarification": False}
    if NORAG_RX.search(t):
        verbs = ["повтори","сократи","переведи","выпиши","удали","перефразируй","резюме"]
        anchors = []
        if history:
            ans = (history[-1].get("content") if history[-1].get("role")=="assistant" else "") if len(history)==1 else ""
            if not ans and len(history)>=2 and history[-2].get("role")=="assistant":
                ans = history[-2].get("content","")
            if ans:
                al = ans.lower()
                anchors = [k for k in ["итого","сумма","средний","количество","код","продукт","дата","ключ","версия","определение","правило","порог"] if k in al]
        if any(v in t for v in verbs) and anchors:
            return {"intent": "no_rag", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

