            return {"intent": "data_catalog", "needs_clarification": True}
        return {"intent": "data_catalog", "needs_clarification": False}
    if NORAG_RX.search(t):
        return {"intent": "no_rag", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

# regex_based.py
"""Soft regex baseline for 8-class dialogue intent classification with critical guardrails."""
import re
from helper import load_examples, last_assistant

# Intent patterns — compact, focused, ordered by priority after guards
GREETING_RX = re.compile(r"\b(привет|здравств|добр(?:ый|ое)|свидания|увидимся)\b")
GRATITUDE_RX = re.compile(r"(?:спасибо|благодар|спс|помогло)")
CAPABILITIES_RX = re.compile(
    r"(?:ты умеешь|твои (?:функции|возможности|навыки)|"
    r"кто ты(?:\s+такой)?|\bкто ты\b|о себе|перечисли (?:свои )?возможности|что ты)"
)
SUPPORT_RX = re.compile(
    r"(?:оператор|специалист|поддержк|живой человек|свяжи|пригласи)"
)
CATALOG_RX = re.compile(
    r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис)"
)
PIVOT_RX = re.compile(
    r"(?:сводн|построй|сгруппируй|срез|кросс|отсортируй|поменяй местами|убери разрез|добавь фильтр|сделай таблиц|табличку)"
)
NORAG_RX = re.compile(
    r"(?:повтори|сократи|переведи|выпиши|удали|перефразируй|резюме разговора|какой код ошибки я|про какой продукт мы говорили)"
)
WORK_RX = re.compile(
    r"(почему|ошибк|не работает|не открывается|не грузится|методик|регламент|что такое|объясни|расскажи|срок|сколько)"
)

# Negations that flip Support -> Technical when asking to explain instead of connect
SUPPORT_NEG_RX = re.compile(
    r"(?:не\s+(?:зови|подключай|надо|вызывай|созывай))|оператора\s+не|специалиста\s+не"
)

def _context(history, text):
    t = (text or "").lower()
    last = (last_assistant(history) or "").lower()

    # Context-pair disambiguation: menu choices map to different intents depending on previous offer
    if any(k in t for k in ["вариант 2", "второе", "пункт а", "пункт б"]):
        if any(k in last for k in ["оператор", "специалист", "человек"]):
            return {"intent": "support", "needs_clarification": False}
        if any(k in last for k in ["объясн", "методик", "подробн", "разбор"]):
            return {"intent": "technical", "needs_clarification": False}

    # Continue listing only after a catalog response (remove fragile dependence on exact nouns)
    if any(k in t for k in [
        "покажи ещё", "покажи еще", "следующие объекты", "дальше",
        "другие", "ещё раз", "далее"
    ]) and ("объект" in last or "таблиц" in last or "витрин" in last or "куб" in last):
        return {"intent": "data_catalog", "needs_clarification": False}

    # Table formatting is no_rag only when facts are already present
    if "оформи это таблицей" in t and any(k in last for k in [
        "итого", "сумма", "средний", "количество", "строки", "столбцы",
        "значение", "доход", "оборот", "число", "фильтр", "квартал", "месяц"
    ]):
        return {"intent": "no_rag", "needs_clarification": False}

    # Month-specific numeric continuation implies new numbers needed from history-aware request
    if re.search(r"\bа за\s+\w+[\?\u0430-я]*\b", t) and (
        "за" in last and any(x in last for x in ["руб","арк","шт","клиент","остат","сумм","доход","оборот"])
    ):
        return {"intent": "pivot_table", "needs_clarification": False}

    return None

def _predict_one(history, text):
    t = (text or "").lower()

    # Highest priority: contextual overrides informed by the last assistant turn
    ctx = _context(history, t)
    if ctx:
        return ctx

    # Negation flips must precede affirmative support detection
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}
    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Work/task indicators suppress polite openings like greeting/thanks
    has_work_marker = bool(WORK_RX.search(t))
    if GREETING_RX.search(t):
        # Boundary-safe farewell/greeting: exclude bare 'пока' unless part of a task phrase
        m_farewell = re.search(r"\bпока\b", t)
        has_task_tail = "таблиц" in t or "почему" in t or "ошибк" in t or "не открыва" in t
        if not m_farewell or has_task_tail:
            pass  # allow fallthrough to technical/work rules
        else:
            return {"intent": "greeting", "needs_clarification": False}
    elif GRATITUDE_RX.search(t):
        if not has_work_marker:
            return {"intent": "gratitude", "needs_clarification": False}

    # Early win for platform/product questions vs self-referential capabilities
    if re.search(r"\b(платформ|меридиан|призм)\b", t):
        return {"intent": "technical", "needs_clarification": False}

    # Explicit build/edit actions take precedence over generic catalog mentions
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}
    if CATALOG_RX.search(t):
        has_search = bool(re.search(r"(?:найди|покажи|выведи|где)", t))
        info_intent = bool(re.search(r"(?:информац|сведени)", t))
        nouns = bool(re.search(
            r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис)", t))
        # Clarify only when user asks about information without an explicit search verb
        if not has_search and info_intent and nouns:
            return {"intent": "data_catalog", "needs_clarification": True}
        return {"intent": "data_catalog", "needs_clarification": False}
    if CAPABILITIES_RX.search(t):
        return {"intent": "capabilities", "needs_clarification": False}
    if NORAG_RX.search(t):
        return {"intent": "no_rag", "needs_clarification": False}

    # Default fallback class
    return {"intent": "technical", "needs_clarification": False}

def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

