SUPPORT_NEG_RX = re.compile(
    r"(?:не\s+(?:зови|подключай|надо|вызывай|созывай)\s*(?:оператора|специалиста|его)?)|"
    r"(?:без оператора)|"
    r"(?:оператора не)|"
    r"(?:специалиста не)"
)
# Exception: explicit request sequence where negation targets repetition, not connection.
SUPPORT_EXPLICIT_RX = re.compile(
    r"не повтори.*лучше позови"
)


