# regex_based.py
"""Soft regex baseline for 8-class dialogue intent classification with targeted guards."""
import re
from helper import load_examples

# Class-focused regexes — keep tight to avoid cross-intent bleed
GREETING_RX = re.compile(r"\b(привет|здравств|добр(?:ый|ое)|свидания|увидимся)\b")
GRATITUDE_RX = re.compile(
    r"(?:спасибо|благодар|спс|помогло|на этом всё|вопросов больше нет)"
)
CAPABILITIES_RX = re.compile(
    r"(?:ты умеешь|твои (?:функции|возможности|навыки)|кто ты(?: такой)?\b|о себе|перечисли (?:свои )?возможности)"
)
SUPPORT_RX = re.compile(r"(?:оператор|специалист|поддержк|живой человек|свяжи|пригласи)")
CATALOG_RX = re.compile(r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|покажи ещё)")
PIVOT_RX = re.compile(r"(?:сводн|построй|сгруппируй|срез|кросс)")
NORAG_RX = re.compile(
    r"(?:повтори|сократи|переведи|выпиши|удали|перефразируй|резюме разговора|"
    r"какой код ошибки я|\bпро какой продукт\b|сколько пунктов было в твоём списке)"
)
SUPPORT_NEG_RX = re.compile(r"не\s+(?:зови|подключай|надо|вызывай|созывай)")
WORK_RX = re.compile(
    r"почему|ошибк|не работает|не открывается|не грузится|что такое|объясни|методик|регламент|срок хранени"
)
FAREWELL_BOUNDARY_RX = re.compile(r"\bпока\b")  # whole-word farewell boundary


def _last_assistant(history):
    if not history:
        return ""
    for h in reversed(history):
        if h.get("role") == "assistant":
            return (h.get("content") or "").lower()
    return ""


def _predict_one(history, text):
    t = (text or "").lower()

    # Negations flip support -> technical when asking to explain instead of connect
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}

    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Context pairs that override plain keyword matches
    last = _last_assistant(history)
    tt = t.strip()
    if ("вариант 2" in tt or "второе" in tt or "пункт б" in tt):
        if any(k in last for k in ["оператор", "специалист"]):
            return {"intent": "support", "needs_clarification": False}
        if any(k in last for k in ["объясн", "методик", "подробн"]):
            return {"intent": "technical", "needs_clarification": False}

    # Work markers override polite openings
    if WORK_RX.search(t):
        if GRATITUDE_RX.search(t):
            return {"intent": "technical", "needs_clarification": False}
        m_greet = GREETING_RX.search(t)
        if m_greet:
            is_farewell = bool(FAREWELL_BOUNDARY_RX.search(t))
            has_task_tail = re.search(r"пока\s+таблиц", t) is not None
            if is_farewell and not has_task_tail:
                return {"intent": "greeting", "needs_clarification": False}
            # else fall through to technical due to co-occurring work marker

    # CRITICAL ORDER: pivot_table must be checked before data_catalog
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}

    if CATALOG_RX.search(t):
        # Disambiguate continued listing from a fresh request using context
        clar = bool(
            re.search(r"(?:информац|сведени)", t)
            and not re.search(r"(?:найди|покажи|выведи|где)", t)
        )
        last_la = last
        if "покажи ещё" in tt or "следующие" in tt or "дальше" in tt:
            if any(k in last_la for k in ["найден", "показа", "перв", "объект", "таблиц", "витрин", "куб", "дашборд"]):
                return {"intent": "data_catalog", "needs_clarification": clar}
            return {"intent": "technical", "needs_clarification": False}
        return {"intent": "data_catalog", "needs_clarification": clar}

    if CAPABILITIES_RX.search(t):
        return {"intent": "capabilities", "needs_clarification": False}

    if NORAG_RX.search(t):
        return {"intent": "no_rag", "needs_clarification": False}

    # Clean greeting after all overrides
    m_greet = GREETING_RX.search(t)
    if m_greet:
        is_farewell = bool(FAREWELL_BOUNDARY_RX.search(t))
        has_task_tail = re.search(r"пока\s+таблиц", t) is not None
        if is_farewell and has_task_tail:
            pass  # allow fallthrough (likely technical)
        else:
            return {"intent": "greeting", "needs_clarification": False}

    if GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

