)
NORAG_RX = re.compile(
    r"(?:повтори|сократи|переведи|выпиши|удали|перефразируй|резюме разговора|собери краткое резюме|собери краткое резюме нашего разговора|какой код ошибки я|про какой продукт мы говорили|сколько пунктов было в твоём списке|верни только дату|какие два варианта ты только что предложил)"
)
WORK_RX = re.compile(
    r"(почему|ошибк|не работает|не открывается|не грузится|методик|регламент|что такое|объясни|расскажи|срок|сколько|как счита|какой регламент)"
)

