    if re.search(r"\b(сколько пунктов было|какие два варианта ты)\b", t):
        hist_text = " ".join((h.get("content") or "") for h in (history or [])).lower()
        # Strengthened condition from program insights: require corresponding history terms
        if ("пункт" in hist_text and "ответ" in hist_text and "было" in hist_text) or \
           ("вариант" in hist_text and "предложил" in hist_text and "два" in hist_text):
            return {"intent": "no_rag", "needs_clarification": False}
    return None


def _predict_one(history, text):
