    if re.search(rf"\bа за\s+{months}\b", t) and any(m in last for m in ["январ","феврал","март","апрел","ма","июн","июл","август","сентябр","октябр","ноябр","декабр"]):
        return {"intent": "pivot_table", "needs_clarification": False}

