)
NORAG_RX = re.compile(
    r"(?:повтори|сократи|переведи|выпиши|удали|перефразируй|резюме разговора|какой код ошибки я|про какой продукт мы говорили|сколько пунктов было в твоём списке|верни только дату|какие два варианта ты только что предложил|что ты ответил выше\?)"
)
WORK_RX = re.compile(
    r"(почему|ошибк|не работает|не открывается|не грузится|методик|регламент|что такое|объясни|расскажи|срок|сколько|как счита|какой регламент)"
)

# Negations that flip Support -> Technical. Require operator/specialist word in the same clause; exclude 'не повторяй'.
SUPPORT_NEG_RX = re.compile(
    r"(?:не\s+(?:зови|подключай|надо|вызывай|созывай)\s*(?:оператора|специалиста|его)?)|"
    r"(?:без оператора)|"
    r"(?:оператора не)|"
    r"(?:специалиста не)|"
    r"(?:не повторяй инструкцию, лучше позови оператора)"
)


def _context(history, text):
    t = (text or "").lower()
    last = (last_assistant(history) or "").lower()
    # Context-pair disambiguation: operator menu vs explanation menu
    if any(k in t for k in ["вариант 2", "второе", "пункт б", "пункт а"]):
        if any(k in last for k in ["оператор", "специалист", "человек"]):
            return {"intent": "support", "needs_clarification": False}
        if any(k in last for k in ["объясн", "методик", "подробн", "разбор"]):
            return {"intent": "technical", "needs_clarification": False}
    # Continue listing after catalog response — relax keyword dependence to avoid misses
    if any(k in t for k in [
        "покажи ещё", "покажи еще", "следующие объекты", "дальше",
        "другие", "ещё раз", "далее", "другие объекты"
    ]):
        return {"intent": "data_catalog", "needs_clarification": False}
    # Table formatting when facts already present
    if "оформи это таблицей" in t and any(k in last for k in [
        "итого", "сумма", "средний", "количество", "строки", "столбцы",
        "значение", "доход", "оборот", "число", "фильтр", "квартал", "месяц",
        "факт", "ключ"
    ]):
        return {"intent": "no_rag", "needs_clarification": False}
    # Month-specific numeric continuation after a numbers-bearing assistant turn
    m = re.search(r"\bа за\s+(\w+)[\?\u0430-я]*\b", t)
    if m:
        # Trigger on recent months/pivot cues regardless of exact units presence
        if any(x in last for x in ["руб","арк","шт","клиент","остат","сумм","доход","оборот","за август","за июль","за июнь"]):
            return {"intent": "pivot_table", "needs_clarification": False}
    # When user asks about timing and the exact date was already provided above
    if "когда она начинает действовать" in t and re.search(r"\d{1,2}\s+[а-я]+\s+\d{4}", last):
        return {"intent": "no_rag", "needs_clarification": False}
    # Dialogue-about-itself questions not covered by NORAG_RX list yet
    if re.search(r"\b(сколько пунктов было|какие два варианта ты|что ты ответил выше)\b", t):
        hist_text = " ".join((h.get("content") or "") for h in (history or [])).lower()
        if ("пункт" in hist_text and "ответ" in hist_text) or ("вариант" in hist_text and "предложил" in hist_text) or ("ответ" in hist_text and "выше" in t):
            return {"intent": "no_rag", "needs_clarification": False}
    # Standalone farewell handled as greeting unless it carries work markers
    if re.search(r"\bпока\b", t) and not re.search(r"(таблиц|почему|ошибк)", t):
        return {"intent": "greeting", "needs_clarification": False}
    return None


def _predict_one(history, text):
    t = (text or "").lower()

    # Highest priority: contextual overrides
    ctx = _context(history, t)
    if ctx:
        return ctx

    # Negation flips before affirmative support
    if SUPPORT_NEG_RX.search(t):
        return {"intent": "technical", "needs_clarification": False}
    if SUPPORT_RX.search(t):
        return {"intent": "support", "needs_clarification": False}

    # Work markers suppress polite openings
    if (GREETING_RX.search(t) or GRATITUDE_RX.search(t)) and WORK_RX.search(t):
        pass  # fall through to work-related checks below
    elif GREETING_RX.search(t):
        # Boundary-safe farewell/greeting handled by regex's negative lookahead and context rule
        return {"intent": "greeting", "needs_clarification": False}
    elif GRATITUDE_RX.search(t):
        return {"intent": "gratitude", "needs_clarification": False}

    # Capabilities must be checked before generic platform-product keyword catch-all
    if CAPABILITIES_RX.search(t):
        return {"intent": "capabilities", "needs_clarification": False}

    # Early technical win on platform/product questions over other classes
    if re.search(r"\b(платформ|меридиан|призм)\b", t):
        return {"intent": "technical", "needs_clarification": False}

    # Order matters: explicit build/edit requests first
    if PIVOT_RX.search(t):
        return {"intent": "pivot_table", "needs_clarification": False}
    if CATALOG_RX.search(t):
        has_search = bool(re.search(r"(?:найди|покажи|выведи|где)", t))
        info_intent = bool(re.search(r"(?:информац|сведени|что у вас по)", t))
        cat_nouns = bool(re.search(r"(?:витрин|таблиц|куб|дашборд|объект данных|набор данных|представлени|инфосервис)", t))
        # Ambiguous mention without search verb → ask for clarification only when it's genuinely between find vs explain
        if not has_search and info_intent and cat_nouns:
            return {"intent": "data_catalog", "needs_clarification": True}
        return {"intent": "data_catalog", "needs_clarification": False}
    if NORAG_RX.search(t):
        return {"intent": "no_rag", "needs_clarification": False}

    return {"intent": "technical", "needs_clarification": False}


def entrypoint():
    rows = load_examples()
    return {
        r["id"]: _predict_one(r.get("history") or [], r.get("text") or "")
        for r in rows
    }

